const bar=document.querySelector('.reading-progress');function progress(){const max=document.documentElement.scrollHeight-innerHeight;bar.style.width=(max>0?scrollY/max*100:0)+'%'}addEventListener('scroll',progress,{passive:true});progress();
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{rootMargin:'0px 0px -35px 0px',threshold:.05});document.querySelectorAll('.section-heading').forEach(h=>observer.observe(h));document.querySelectorAll('.hero-letter').forEach(letter=>letter.addEventListener('pointerenter',e=>{for(let i=0;i<6;i++){const dot=document.createElement('i');dot.className='pointer-spark';dot.style.cssText=`left:${e.clientX}px;top:${e.clientY}px;--dx:${(Math.random()-.5)*100}px;--dy:${-20-Math.random()*90}px;background:${['#e4f867','#81edaa','#edcd63'][i%3]}`;document.body.append(dot);setTimeout(()=>dot.remove(),1000)}}))}
document.querySelector('.film-play')?.addEventListener('click',()=>{document.querySelector('.film-stage').innerHTML='<iframe src="https://player.vimeo.com/video/1139853510?autoplay=1" title="Food Pantone 项目影片" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>'});
const modal=document.querySelector('#lightbox'),close=document.querySelector('.lightbox-close');document.querySelectorAll('figure img').forEach(im=>{if(im.closest('.device'))return;im.tabIndex=0;im.setAttribute('role','button');im.setAttribute('aria-label','放大：'+im.alt);const open=()=>{modal.querySelector('img').src=im.src;modal.querySelector('img').alt=im.alt;modal.showModal();close.hidden=false;close.focus()};im.addEventListener('click',open);im.addEventListener('keydown',e=>{if(e.key==='Enter')open()})});function shut(){modal.close();close.hidden=true}close.onclick=shut;modal.addEventListener('click',shut);modal.addEventListener('close',()=>close.hidden=true);

modal.appendChild(close);
